const locations=[['✦','학군','학교·학원가','교육 선호가 모이는 생활권','범어·만촌 생활권은 학교 접근성과 학원가 이용 편의가 결합된 대표 교육 생활권입니다.','학교 배정은 주소·학년도별 확인|학원가 접근성은 범어네거리·만촌권 중심 비교|도보 통학 안전성도 함께 검토'],['↗','도로 교통','간선도로·IC','도심과 광역 이동의 균형','달구벌대로·동대구로 등 주요 축 접근성이 생활권별 이동 편의를 좌우합니다.','출퇴근 정체와 우회 경로 확인|수성IC·동대구IC 접근 시간 비교|직장 위치별 체감 입지 검토'],['ⓜ','지하철','2·3호선','역세권은 생활권의 연결망','대구 2호선과 3호선 역 접근성이 수성구 내부 및 도심 이동 편의를 높입니다.','실제 도보 동선과 경사 확인|환승 횟수와 배차 간격 고려|소음·혼잡 등 상충 요인 점검'],['K','KTX','동대구역 연계','광역 이동은 동대구역이 기준','수성구 내 KTX역은 없으며 도로·버스·도시철도를 통한 동대구역 접근 시간을 비교해야 합니다.','생활권별 환승 경로 확인|시간대별 소요시간 분리 검토|택시·자가용 승하차 편의 고려'],['G','광역철도','계획 교통','GTX가 아닌 대구권 광역철도 관점','수도권 GTX가 수성구에 직접 운행되는 것으로 오해하면 안 됩니다. 대구권 광역철도와 장래 계획은 확정 여부를 구분해야 합니다.','운영·공사·계획 단계 구분|공식 고시와 사업 진행률 우선|예정망 프리미엄은 보수적 평가']];
const deals=[['범어W','범어동','84.9㎡','12억 8,000만','10.18','21층'],['힐스테이트범어','범어동','84.8㎡','11억 9,000만','10.17','15층'],['두산위브더제니스','범어동','129.0㎡','18억 7,000만','10.16','31층'],['만촌삼정그린코아','만촌동','84.9㎡','9억 4,000만','10.15','12층'],['수성SK리더스뷰','두산동','110.5㎡','15억 6,000만','10.14','28층'],['수성알파시티청아람','노변동','84.7㎡','6억 9,000만','10.12','10층']];
function chart(type='sale',period=12){let a=series[type].slice(-period),m=months.slice(-period),w=700,h=240,p=34,x=i=>p+i*(w-p*2)/(a.length-1||1),y=v=>h-p-(v-97)/7*(h-p*2),path=a.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');lineChart.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${[98,100,102,104].map(v=>`<line x1="${p}" y1="${y(v)}" x2="${w-p}" y2="${y(v)}" stroke="#e1e5e2"/><text x="2" y="${y(v)+3}" class="axis-label">${v}</text>`).join('')}<line x1="${p}" y1="${y(100)}" x2="${w-p}" y2="${y(100)}" stroke="#ef6d36" stroke-dasharray="5 5"/><path d="${path}" fill="none" stroke="#0d6b46" stroke-width="4"/>${a.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="#fff" stroke="#0d6b46" stroke-width="3"><title>${m[i]} ${v}</title></circle><text x="${x(i)}" y="232" text-anchor="middle" class="axis-label">${m[i]}</text>`).join('')}</svg>`}
function rank(id,type,vals){document.querySelector('#'+id).innerHTML=names.map((n,i)=>`<div class="rank-item"><span class="num">${i+1}</span><div><b>${n}</b><small>${['범어동','두산동','범어동','두산동','범어동','만촌동','노변동','범어동','수성동','황금동'][i]} · 전용 ${i%3?84.9:129}㎡</small></div><strong>${vals[type][i]}<small>${type==='monthly'?'보증금 / 월세':'샘플 신고가'}</small></strong></div>`).join('')}
function rows(q=''){dealRows.innerHTML=deals.filter(r=>r.join(' ').includes(q)).map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="6">검색 결과가 없습니다.</td></tr>'}
document.querySelectorAll('.tabs').forEach(t=>t.onclick=e=>{if(!e.target.matches('button'))return;t.querySelectorAll('button').forEach(b=>b.classList.remove('active'));e.target.classList.add('active');let type=e.target.dataset.type,target=t.dataset.target;target==='chart'?chart(type,+periodFilter.value):rank(target,type,target==='dealRank'?ranking:pyeong)});
locationCards.innerHTML=locations.map((x,i)=>`<button class="location-card" data-i="${i}"><span class="icon">${x[0]}</span><b>${x[1]}</b><span>${x[2]}</span></button>`).join('');locationCards.onclick=e=>{let b=e.target.closest('button');if(!b)return;document.querySelectorAll('.location-card').forEach(x=>x.classList.remove('active'));b.classList.add('active');let x=locations[+b.dataset.i];locationDetail.className='location-detail open';locationDetail.innerHTML=`<div><span class="kicker">${x[1]}</span><h3>${x[3]}</h3></div><div><p>${x[4]}</p><ul>${x[5].split('|').map(p=>`<li>${p}</li>`).join('')}</ul></div>`};
periodFilter.onchange=e=>chart(document.querySelector('[data-target="chart"] .active').dataset.type,+e.target.value);searchInput.oninput=e=>rows(e.target.value.trim());resetBtn.onclick=()=>{document.querySelectorAll('select').forEach(s=>s.selectedIndex=0);chart()};downloadBtn.onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff단지명,지역,전용면적,거래가,거래일,층\n'+deals.map(r=>r.join(',')).join('\n')],{type:'text/csv'}));a.download='suseong-apartment-demo.csv';a.click()};chart();rank('dealRank','sale',ranking);rank('pyeongRank','sale',pyeong);rows();
